from pathlib import Path
import base64
from io import BytesIO
from PIL import Image

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "assets" / "the-uni-social-transparent-1200x630-20261011.png"

# Exact approved transparent THE UNI artwork, embedded as an optimized PNG source.
# The workflow only places this artwork on a 1200x630 transparent social canvas;
# it does not redesign, recolor, or add a background.
SOURCE_B64 = """"""

raw = base64.b64decode(SOURCE_B64, validate=True)
with Image.open(BytesIO(raw)) as src:
    src.load()
    if src.format != "PNG":
        raise RuntimeError(f"Unexpected embedded source format: {src.format}")
    artwork = src.convert("RGBA")

# Preserve the approved artwork's aspect ratio and place it safely inside a 1200x630 card.
target_w = 1080
target_h = round(artwork.height * target_w / artwork.width)
artwork = artwork.resize((target_w, target_h), Image.Resampling.LANCZOS)

preview = Image.new("RGBA", (1200, 630), (0, 0, 0, 0))
x = (1200 - target_w) // 2
y = (630 - target_h) // 2 - 8
preview.alpha_composite(artwork, (x, y))

OUT.parent.mkdir(parents=True, exist_ok=True)
preview.save(OUT, "PNG", optimize=True, compress_level=9)

with Image.open(OUT) as check:
    check.load()
    if check.size != (1200, 630):
        raise RuntimeError(f"Unexpected social preview size: {check.size}")
    if check.format != "PNG":
        raise RuntimeError(f"Unexpected social preview format: {check.format}")
    if "A" not in check.mode:
        raise RuntimeError(f"Social preview lost transparency: {check.mode}")

print(f"Generated transparent THE UNI social preview: {OUT} ({OUT.stat().st_size} bytes)")
